import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import ghidra.app.script.GhidraScript;
import ghidra.pcode.exec.*;
import ghidra.program.model.address.AddressSet;
import ghidra.program.model.symbol.SourceType;
public class C6000PipelineDpTest extends GhidraScript {
 protected void run()throws Exception{
  c6000.C6000PacketContext.prime(currentProgram,monitor);var arithmetic=BytesPcodeArithmetic.forLanguage(currentProgram.getLanguage());int count=0;var records=new JsonArray();
  for(var element:JsonParser.parseString(Files.readString(Paths.get(getScriptArgs()[0]))).getAsJsonArray()){
   var row=element.getAsJsonObject();var at=toAddr(row.get("entry").getAsLong());var name=row.get("name").getAsString();var function=currentProgram.getFunctionManager().createFunction(name,at,new AddressSet(at,at.add(row.has("extent")?row.get("extent").getAsInt():0xff)),SourceType.USER_DEFINED);if(row.has("refused")){new ghidra.app.cmd.disassemble.DisassembleCommand(at,new AddressSet(at,at.add(3)),false).applyTo(currentProgram,monitor);boolean refused=false;try{c6000.C6000PipelineSchedules.enable(currentProgram,function,"Synthetic drained entry",Set.of(),monitor);}catch(IllegalArgumentException error){if(!error.getMessage().contains(row.get("refused").getAsString()))throw error;refused=true;}if(!refused)throw new AssertionError("Invalid schedule accepted: "+name);var context=currentProgram.getProgramContext().getValue(currentProgram.getRegister("c_schedule_entry"),at,false);if(java.math.BigInteger.ONE.equals(context))throw new AssertionError("Refusal mutated entry context");records.add(row);count++;continue;}var result=new c6000.C6000PipelineCompiler(currentProgram,function).compile();
   var state=new BytesPcodeExecutorState(currentProgram.getLanguage(),PcodeStateCallbacks.NONE);for(var register:currentProgram.getLanguage().getRegisters())if(!register.isProcessorContext()&&register.getMinimumByteSize()==4)state.setVar(register,arithmetic.fromConst(0,4));state.setVar(currentProgram.getRegister("B3"),arithmetic.fromConst(0x9000,4));for(var item:row.getAsJsonObject("input").entrySet())state.setVar(currentProgram.getRegister(item.getKey()),arithmetic.fromConst(item.getValue().getAsLong(),4));
   if(row.has("memory")){state.setVar(toAddr(0x8000),512,false,new byte[512]);for(var item:row.getAsJsonObject("memory").entrySet())state.setVar(toAddr(Long.parseLong(item.getKey())),4,false,arithmetic.fromConst(item.getValue().getAsLong(),4));}
   var executor=new PcodeExecutor<byte[]>(state,PcodeExecutorStatePiece.Reason.EXECUTE_READ);var library=PcodeUseropLibrary.<byte[]>nil();var frame=executor.begin(Arrays.asList(result.code()),library.getSymbols((ghidra.app.plugin.processors.sleigh.SleighLanguage)currentProgram.getLanguage()));int steps=0,cycles=0,stalls=0;while(!frame.isFinished()&&steps++<100000){int index=frame.index();if(result.cycleStarts().containsKey(index))cycles++;executor.step(frame,library);if(result.stallTargets().containsKey(index)&&frame.index()==result.stallTargets().get(index))stalls++;}if(!frame.isFinished())throw new AssertionError("Step bound "+name);if(row.has("expected_cycles")&&cycles+stalls!=row.get("expected_cycles").getAsInt())throw new AssertionError(name+" cycles="+(cycles+stalls));
   for(var expected:row.getAsJsonObject("expected").entrySet()){long value=arithmetic.toLong(state.getVar(currentProgram.getRegister(expected.getKey()),PcodeExecutorStatePiece.Reason.INSPECT),PcodeArithmetic.Purpose.INSPECT);if(value!=expected.getValue().getAsLong())throw new AssertionError(name+" "+expected.getKey()+"="+Long.toHexString(value)+" expected="+Long.toHexString(expected.getValue().getAsLong()));}if(row.has("expected_memory"))for(var item:row.getAsJsonObject("expected_memory").entrySet()){long value=arithmetic.toLong(state.getVar(toAddr(Long.parseLong(item.getKey())),4,false,PcodeExecutorStatePiece.Reason.INSPECT),PcodeArithmetic.Purpose.INSPECT);if(value!=item.getValue().getAsLong())throw new AssertionError(name+" memory "+item.getKey()+"="+Long.toHexString(value)+" expected="+Long.toHexString(item.getValue().getAsLong()));}
   var actual=new JsonObject();for(String bank:List.of("A","B"))for(int k=0;k<32;k++){String register=bank+k;actual.addProperty(register,arithmetic.toLong(state.getVar(currentProgram.getRegister(register),PcodeExecutorStatePiece.Reason.INSPECT),PcodeArithmetic.Purpose.INSPECT));}for(String register:List.of("ILC","RILC","TSR"))actual.addProperty(register,arithmetic.toLong(state.getVar(currentProgram.getRegister(register),PcodeExecutorStatePiece.Reason.INSPECT),PcodeArithmetic.Purpose.INSPECT));row.add("actual",actual);row.addProperty("cycles",cycles+stalls);row.addProperty("stalls",stalls);row.addProperty("states",result.states());row.addProperty("operations",result.code().length);records.add(row);
   if(getScriptArgs().length>1&&(name.equals("SPLOOP_3_7")||name.equals("SPLOOPW_3_0")||name.equals("add_late_high_split")||name.equals("mpydp_late_high_split")||name.equals("subdp_reversed_late_high"))){
    new ghidra.app.cmd.disassemble.DisassembleCommand(at,new AddressSet(at,at.add(3)),false).applyTo(currentProgram,monitor);function.setReturnType(ghidra.program.model.data.UnsignedIntegerDataType.dataType,SourceType.USER_DEFINED);c6000.C6000PipelineSchedules.enable(currentProgram,function,"Synthetic initially drained pipeline",Set.of(),monitor);var decompiler=new ghidra.app.decompiler.DecompInterface();decompiler.setOptions(new ghidra.app.decompiler.DecompileOptions());decompiler.openProgram(currentProgram);try{var dec=decompiler.decompileFunction(function,30,monitor);if(!dec.decompileCompleted())throw new AssertionError(dec.getErrorMessage());Files.writeString(Paths.get(getScriptArgs()[0]+"."+name+".c"),dec.getDecompiledFunction().getC());}finally{decompiler.dispose();}
   }
   println("DP_CASE "+name+" cycles="+(cycles+stalls));count++;
  }Files.writeString(Paths.get(getScriptArgs()[0]+".results.json"),new GsonBuilder().setPrettyPrinting().create().toJson(records));println("C6000_PIPELINE_DP_OK cases="+count);
 }
}
